return [{ json: {
  shop: 'REPLACE_STORE.myshopify.com', amazon_seller_id: 'REPLACE_AMAZON_SELLER_ID', amazon_marketplace: 'A21TJRUUN4KGV',
  lwa_client_id: 'REPLACE_LWA_CLIENT_ID', lwa_client_secret: 'REPLACE_LWA_CLIENT_SECRET', lwa_refresh_token: 'REPLACE_LWA_REFRESH_TOKEN',
  flipkart_location_id: 'REPLACE_FLIPKART_LOCATION_ID', full_sync_hour_utc: 20, interval_min: 10, overlap_min: 5, first_run_lookback_h: 24,
  velocity_days: 14, run_started: new Date().toISOString()
} }];

const f = $input.first().json;
const q = Number(f['Quantity']);
if (!f['SKU'] || isNaN(q) || q < 0) return [];
return [{ json: { adj_id: `ADJ-${$now.toFormat('yyMMddHHmmss')}-${Math.random().toString(36).slice(2, 5)}`, sku: String(f['SKU']).trim(),
  type: f['Type'], qty: q, note: f['Reference / note'] || '', by: f['Done by'], status: 'pending', created_at: new Date().toISOString() } }];

const cfg = $('Set Sync Config').first().json;
const st = $input.all().map(i => i.json).find(r => r.key === 'orders_cursor');
const since = st?.value ? new Date(new Date(st.value).getTime() - cfg.overlap_min * 60000) : new Date(Date.now() - cfg.first_run_lookback_h * 3600000);
// Amazon requires LastUpdatedAfter at least 2 minutes in the past
return [{ json: { ...cfg, since: since.toISOString(), since_amazon: new Date(Math.min(since.getTime(), Date.now() - 180000)).toISOString(), now: cfg.run_started } }];

const o = ($input.first().json.body?.payload?.Orders || [])
  .filter(x => ['Unshipped', 'PartiallyShipped', 'Shipped', 'Canceled'].includes(x.OrderStatus));
return o.length ? o.map(x => ({ json: { order_id: x.AmazonOrderId, status: x.OrderStatus, updated: x.LastUpdateDate } })) : [{ json: { none: true } }];

const cfg = $('Resolve Order Cursor').first().json;
const nowISO = new Date().toISOString(), today = nowISO.slice(0, 10);
const gid = (t, id) => String(id).startsWith('gid://') ? String(id) : `gid://shopify/${t}/${id}`;
const master = $('Read Inventory Master').all().map(i => i.json).filter(r => r.sku && String(r.active ?? 'yes').toLowerCase() !== 'no');
const by = {}, alias = { shopify: {}, amazon: {}, flipkart: {} };
for (const r of master) {
  const s = String(r.sku).trim();
  by[s] = { ...r, sku: s, on_hand: Number(r.on_hand) || 0, start: Number(r.on_hand) || 0 };
  alias.shopify[String(r.sku).trim()] = s;
  if (r.amazon_sku) alias.amazon[String(r.amazon_sku).trim()] = s;
  if (r.flipkart_sku) alias.flipkart[String(r.flipkart_sku).trim()] = s;
}
const processed = $('Read Processed Lines').all().map(i => i.json).filter(p => p.key);
const seen = new Set(processed.map(p => p.key));
const lines = [], errors = [];
// ---- Shopify
const sh = $('Fetch Changed Shopify Orders').first().json;
if (sh.statusCode !== 200) errors.push(`Shopify orders: HTTP ${sh.statusCode}`);
for (const e of sh.body?.data?.orders?.edges || []) for (const le of e.node.lineItems.edges)
  lines.push({ channel: 'shopify', order_id: e.node.name, line_id: le.node.id, sku: le.node.sku, qty: le.node.quantity, cancelled: !!e.node.cancelledAt });
// ---- Amazon
if (!$('Get Amazon LWA Token').first().json.access_token) errors.push('Amazon: LWA token failed');
if ($('Fetch Amazon Order Items').isExecuted) {
  const orders = $('Split Amazon Orders').all().map(i => i.json);
  $('Fetch Amazon Order Items').all().forEach((it, i) => { const o = orders[i] || {};
    if (it.json.error) errors.push(`Amazon items ${o.order_id}: ${it.json.error.message || 'error'}`);
    for (const l of it.json.payload?.OrderItems || []) lines.push({ channel: 'amazon', order_id: o.order_id, line_id: l.OrderItemId,
      sku: l.SellerSKU, qty: Number(l.QuantityOrdered) || 0, cancelled: o.status === 'Canceled' }); });
}
// ---- Flipkart
for (const [node, cancelled] of [['Fetch Flipkart Pre-dispatch Shipments', false], ['Fetch Flipkart Cancelled Shipments', true]]) {
  const r = $(node).first().json;
  if (r.statusCode && r.statusCode !== 200) errors.push(`${node}: HTTP ${r.statusCode}`);
  for (const s of r.body?.shipments || []) for (const l of s.orderItems || [])
    lines.push({ channel: 'flipkart', order_id: l.orderId || s.shipmentId, line_id: l.orderItemId || l.id, sku: l.sku, qty: Number(l.quantity) || 0, cancelled });
}
// ---- apply sales & cancellations exactly once
const ledger = [], unknown = new Set();
for (const l of lines) {
  const s = alias[l.channel][String(l.sku || '').trim()];
  if (!s) { unknown.add(`${l.channel}:${l.sku}`); continue; }
  const k = `${l.channel}|${l.line_id}`, kc = `${k}|cancel`;
  if (!l.cancelled && !seen.has(k)) { by[s].on_hand -= l.qty; seen.add(k); ledger.push({ key: k, channel: l.channel, order_id: l.order_id, sku: s, qty: -l.qty, type: 'sale', ts: nowISO }); }
  else if (l.cancelled && seen.has(k) && !seen.has(kc)) { by[s].on_hand += l.qty; seen.add(kc); ledger.push({ key: kc, channel: l.channel, order_id: l.order_id, sku: s, qty: l.qty, type: 'cancel_restock', ts: nowISO }); }
}
// ---- manual adjustments
const adjRows = [];
for (const a of $('Read Pending Adjustments').all().map(i => i.json).filter(a => a.adj_id && a.status === 'pending')) {
  const s = String(a.sku || '').trim(), t = String(a.type || '').toLowerCase(), q = Number(a.qty) || 0;
  if (!by[s]) { adjRows.push({ adj_id: a.adj_id, status: 'error_unknown_sku', applied_at: nowISO }); continue; }
  const before = by[s].on_hand;
  if (/audit|count/.test(t)) by[s].on_hand = q; else if (/receiv|grn|restock|return/.test(t)) by[s].on_hand += Math.abs(q); else by[s].on_hand -= Math.abs(q);
  const d = by[s].on_hand - before;
  adjRows.push({ adj_id: a.adj_id, status: 'applied', applied_at: nowISO, delta: d });
  ledger.push({ key: `adj|${a.adj_id}`, channel: 'manual', order_id: a.adj_id, sku: s, qty: d, type: t, ts: nowISO });
}
// ---- velocity, pushes, alerts
const since = Date.now() - cfg.velocity_days * 864e5, sold = {};
[...processed, ...ledger].filter(p => p.type === 'sale' && new Date(p.ts).getTime() > since).forEach(p => sold[p.sku] = (sold[p.sku] || 0) + Math.abs(Number(p.qty) || 0));
const d = new Date(), full = d.getUTCHours() === cfg.full_sync_hour_utc && d.getUTCMinutes() < cfg.interval_min;
const push = { shopify: [], amazon: [], flipkart: [] }, rows = [], alerts = [];
for (const r of Object.values(by)) {
  const sellable = Math.max(0, r.on_hand - (Number(r.safety_buffer) || 0));
  const changed = full || r.last_pushed_qty === '' || r.last_pushed_qty === undefined || sellable !== Number(r.last_pushed_qty);
  const vel = (sold[r.sku] || 0) / cfg.velocity_days, cover = vel ? Math.round(r.on_hand / vel * 10) / 10 : null;
  if (changed) {
    if (r.shopify_inventory_item_id && r.shopify_location_id) push.shopify.push({ inventoryItemId: gid('InventoryItem', r.shopify_inventory_item_id), locationId: gid('Location', r.shopify_location_id), quantity: sellable });
    if (r.amazon_sku) push.amazon.push({ sku: String(r.amazon_sku), quantity: sellable, master_sku: r.sku });
    if (r.flipkart_sku && r.flipkart_product_id) push.flipkart.push({ sku: String(r.flipkart_sku), product_id: r.flipkart_product_id, location_id: r.flipkart_location_id || cfg.flipkart_location_id, quantity: sellable });
  }
  let lowDay = String(r.last_low_alert || '').slice(0, 10);
  const reorder = Math.max(Number(r.reorder_qty) || 0, Math.ceil(vel * ((Number(r.lead_time_days) || 7) + 14)) - r.on_hand);
  const base = { sku: r.sku, title: r.title || '', on_hand: r.on_hand, sellable, velocity: Math.round(vel * 100) / 100, cover, reorder, supplier: r.supplier || '', lead: r.lead_time_days || '' };
  if (r.on_hand < 0) alerts.push({ level: 'oversold', ...base });
  else if (sellable <= (Number(r.reorder_point) || 0) && lowDay !== today) { alerts.push({ level: sellable === 0 ? 'out' : 'low', ...base }); lowDay = today; }
  if (r.on_hand !== r.start || changed || lowDay !== String(r.last_low_alert || '').slice(0, 10))
    rows.push({ sku: r.sku, on_hand: r.on_hand, sellable, last_pushed_qty: changed ? sellable : r.last_pushed_qty, velocity_per_day: Math.round(vel * 100) / 100,
      days_of_cover: cover ?? '', last_low_alert: lowDay, last_synced_at: nowISO });
}
return [{ json: { push, rows, ledger, adjRows, alerts, errors, unknown: [...unknown].slice(0, 30), full_sync: full,
  stats: { lines: lines.length, applied: ledger.length, skus_changed: rows.length, pushes: push.shopify.length + push.amazon.length + push.flipkart.length },
  cursor: cfg.now } }];

const q = $input.first().json.push.shopify;
const out = [];
for (let i = 0; i < q.length; i += 250) out.push({ json: { body: { query: 'mutation($input: InventorySetQuantitiesInput!){ inventorySetQuantities(input:$input){ userErrors{ field message } } }',
  variables: { input: { name: 'available', reason: 'correction', ignoreCompareQuantity: true, quantities: q.slice(i, i + 250) } } } } });
return out;

const q = $input.first().json.push.flipkart, out = [];
for (let i = 0; i < q.length; i += 10) out.push({ json: { body: Object.fromEntries(q.slice(i, i + 10).map(p =>
  [p.sku, { product_id: p.product_id, locations: [{ id: p.location_id, inventory: p.quantity }] }])) } });
return out;

const c = $input.first().json;
const icon = { oversold: '🔴 OVERSOLD', out: '⛔ OUT OF STOCK', low: '⚠️ LOW' };
const a = c.alerts.sort((x, y) => ['oversold', 'out', 'low'].indexOf(x.level) - ['oversold', 'out', 'low'].indexOf(y.level));
if (!a.length && !c.unknown.length && !c.errors.length) return [];
return [{ json: { text: [`:package: *Stock sync* · ${c.stats.applied} movements · ${c.stats.pushes} channel pushes${c.full_sync ? ' (nightly full sync)' : ''}`,
  ...a.slice(0, 25).map(x => `${icon[x.level]} *${x.sku}* ${x.title} · on hand ${x.on_hand} (sellable ${x.sellable})` +
    (x.velocity ? ` · ${x.velocity}/day · ${x.cover ?? '∞'} days cover` : '') + (x.level !== 'oversold' && x.reorder > 0 ? ` · reorder ~${x.reorder}${x.supplier ? ' from ' + x.supplier : ''}` : '') +
    (x.level === 'oversold' ? ' → cancel or source urgently; all channels set to 0' : '')),
  ...(c.unknown.length ? [`:grey_question: Unmapped channel SKUs: ${c.unknown.join(', ')}`] : []),
  ...(c.errors.length ? [`:x: Pull errors: ${c.errors.join(' · ')}`] : [])].join('\n') } }];

